def find_connected_components(grid):
    """Find connected components of 2-cells using 4-connectivity"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    def dfs(r, c):
        stack = [(r, c)]
        comp = []
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]:
                continue
            visited[cr][cc] = True
            comp.append((cr, cc))

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 2 and not visited[nr][nc]:
                        stack.append((nr, nc))
        return comp

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and not visited[r][c]:
                comp = dfs(r, c)
                components.append(comp)

    return components

